<script setup>
import {computed,nextTick,onMounted,onUnmounted,ref,watch} from 'vue'
import WorkspaceModal from './WorkspaceModal.vue'
import {unitLabel} from '../units'
import {updateColumnFilter,shiftISODate} from '../stock-filter-state'
import {call} from '../api'
import DataTable from './DataTable.vue'
import PurchaseReceiptCosts from './PurchaseReceiptCosts.vue'
import {Button as UiButton} from './ui/button'
import {Input as UiInput} from './ui/input'
import UiSelect from './ui/select/Select.vue'
import {dismissOnBackdrop} from '../dialogs'
const props=defineProps({company:String,warehouse:String,today:String})
const api=(name,args={},write=false)=>call('lotus_farm.warehouse_planning.'+name,args,write)
const data=ref(null),busy=ref(false),saving=ref(false),error=ref(''),notice=ref(''),from=ref(props.today||''),to=ref(shiftISODate(props.today,6)||''),search=ref(''),searchDraft=ref(''),start=ref(0),filters=ref({}),view=ref('coverage')
const detail=ref(null),detailDialog=ref(null),selectedStores=ref({}),request=ref(null),requestDialog=ref(null),confirmAction=ref('')
const order=ref(null),orderDialog=ref(null),receipt=ref(null),receiptDialog=ref(null),receiveDate=ref(props.today||''),receiveQuantities=ref({}),receiveKey=ref(''),receiptConfirm=ref('')
const receiveCosts=ref([]),receiveAccounts=ref([]),receiveDefaultAccount=ref('')
const receiveBaseTotal=computed(()=>(order.value?.items||[]).reduce((sum,r)=>sum+Number(receiveQuantities.value[r.line]||0)*Number(r.rate||0),0))
async function loadReceiveAccounts(){try{const r=await call('lotus_farm.warehouse.receipt_accounts',{company:props.company});receiveAccounts.value=r.accounts||[];receiveDefaultAccount.value=r.default_account||''}catch{receiveAccounts.value=[];receiveDefaultAccount.value=''}}
const sortModel=ref([])
let version=0
const fmt=value=>value==null?'—':Number(value).toLocaleString('vi-VN',{maximumFractionDigits:3})
const warehouseLabel=id=>data.value?.warehouses?.find(w=>w.name===id)?.warehouse_name||id||'—'
const unit=unitLabel
async function load(reset=false){if(reset)start.value=0;if(!props.company)return;if(from.value&&to.value&&from.value>to.value){error.value='Từ ngày không được sau đến ngày.';return}const id=++version;busy.value=true;error.value='';try{const result=await api('overview',{company:props.company,warehouse:props.warehouse,from_date:from.value,to_date:to.value,search:search.value,start:start.value,sort_model:JSON.stringify(sortModel.value),column_filters:JSON.stringify(filters.value)});if(id===version)data.value=result}catch(e){if(id===version)error.value='Không tải được danh sách mới: '+e.message}finally{if(id===version)busy.value=false}}
watch(()=>[props.company,props.warehouse],()=>{filters.value={};load(true)})
onMounted(()=>load(true))
function filter({field,values}){filters.value=updateColumnFilter(filters.value,field,values);load(true)}
let searchTimer=null
watch(searchDraft,value=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{const term=String(value||'').trim();if(term!==search.value){search.value=term;load(true)}},220)})
onUnmounted(()=>clearTimeout(searchTimer))
watch(()=>props.today,value=>{if(value&&!from.value){from.value=value;to.value=shiftISODate(value,6);load(true)}})
function resetFilters(){filters.value={};search.value='';searchDraft.value='';from.value=props.today||'';to.value=shiftISODate(from.value,6);sortModel.value=[];load(true)}
const hasFilters=computed(()=>Object.keys(filters.value).length>0||!!search.value||!!from.value&&!!props.today&&(from.value!==props.today||to.value!==shiftISODate(props.today,6)))
const requestRows=computed(()=>{const q=search.value.toLocaleLowerCase('vi');return (data.value?.requests||[]).filter(r=>!q||[r.name,r.item_name,r.warehouse,r.status].some(x=>String(x||'').toLocaleLowerCase('vi').includes(q)))})
const orderRows=computed(()=>{const q=search.value.toLocaleLowerCase('vi');return (data.value?.orders||[]).filter(r=>!q||[r.name,r.item_name,r.supplier,r.warehouse].some(x=>String(x||'').toLocaleLowerCase('vi').includes(q)))})
const numeric=(field,headerName)=>({field,headerName,minWidth:92,type:'numericColumn',valueFormatter:p=>fmt(p.value)})
const columns=[{field:'item',headerName:'Tên hàng',minWidth:210,flex:1.8,valueFormatter:p=>p.data?p.data.item_name+' · '+p.value:p.value,tooltipValueGetter:p=>p.data.item_name+' · '+p.value},{field:'warehouse',headerName:'Kho cấp',minWidth:130,valueFormatter:p=>warehouseLabel(p.value)},{field:'uom',headerName:'ĐVT',minWidth:65,valueFormatter:p=>unit(p.value)},numeric('remaining_qty','Cần dùng'),numeric('available_qty','Có thể dùng'),numeric('shortage_qty','Còn thiếu'),numeric('incoming_qty','Sắp về'),numeric('to_buy_qty','Cần mua'),{field:'status',headerName:'Tình trạng',minWidth:120}]
const sourceColumns=[{field:'name',headerName:'Nguồn',minWidth:210},{field:'date',headerName:'Ngày cần',minWidth:110},{field:'farm',headerName:'Vườn',minWidth:150},{field:'area',headerName:'Khu vực / lô',minWidth:150},numeric('required_qty','Nhu cầu duyệt'),numeric('issued_qty','Đã cấp'),numeric('draft_qty','Đang lập phiếu'),numeric('remaining_qty','Còn cần cấp')]
const orderColumns=[{field:'name',headerName:'Đơn mua',minWidth:210},{field:'supplier',headerName:'Nhà cung cấp',minWidth:170},{field:'item_name',headerName:'Tên hàng',minWidth:210},{field:'warehouse',headerName:'Kho nhận',minWidth:145,valueFormatter:p=>warehouseLabel(p.value)},numeric('qty','Chưa nhận'),{field:'uom',headerName:'Đơn vị',minWidth:80,valueFormatter:p=>unit(p.value)},{field:'date',headerName:'Dự kiến về',minWidth:110},{field:'overdue',headerName:'Tiến độ',minWidth:110,valueFormatter:p=>p.value?'Quá hẹn':'Đang chờ'}]
const requestColumns=[{field:'name',headerName:'Đề nghị mua',minWidth:210},{field:'item_name',headerName:'Vật tư',minWidth:210},{field:'warehouse',headerName:'Kho nhận',minWidth:145,valueFormatter:p=>warehouseLabel(p.value)},numeric('qty','Chưa mua'),{field:'uom',headerName:'Đơn vị',minWidth:80,valueFormatter:p=>unit(p.value)},{field:'date',headerName:'Ngày cần',minWidth:110},{field:'status',headerName:'Trạng thái',minWidth:110}]
const purchaseItems=[{field:'item_name',headerName:'Vật tư',minWidth:220},numeric('qty','Số lượng'),{field:'uom',headerName:'Đơn vị',valueFormatter:p=>unit(p.value)},{field:'warehouse',headerName:'Kho nhận',minWidth:145,valueFormatter:p=>warehouseLabel(p.value)},{field:'date',headerName:'Ngày cần',minWidth:110}]
async function show(row){detail.value=row;await nextTick();detailDialog.value.showModal()}
async function openRequest(name){try{request.value=await api('purchase_request',{name});confirmAction.value='';await nextTick();requestDialog.value.showModal()}catch(e){error.value=e.message}}
async function buy(row){if(saving.value)return;saving.value=true;error.value='';try{const result=await api('create_purchase_request',{company:props.company,warehouse:row.warehouse,from_date:from.value,to_date:to.value,items:[row.item]},true);notice.value=result.name?'Đã tạo đề nghị mua nháp '+result.name:result.note;detailDialog.value?.close();await load();if(result.name)await openRequest(result.name)}catch(e){error.value=e.message}finally{saving.value=false}}
async function assign(source){if(saving.value)return;saving.value=true;try{await api('assign_warehouse',{company:props.company,requirement:source.name,warehouse:selectedStores.value[source.name]},true);await load()}catch(e){error.value=e.message}finally{saving.value=false}}
async function act(action){if(saving.value)return;saving.value=true;error.value='';try{await api('purchase_action',{name:request.value.name,modified:request.value.modified,action},true);requestDialog.value.close();notice.value=action==='submit'?'Đã duyệt đề nghị mua. Chưa tính là hàng chờ nhập cho tới khi có đơn mua đã duyệt.':'Đã xóa đề nghị mua nháp.';await load()}catch(e){error.value=e.message}finally{saving.value=false}}
const printURL=(doctype,name)=>'/lotus/in-phieu?'+new URLSearchParams({doctype,name})
async function openOrder(name){try{order.value=await api('purchase_order',{name});receiveQuantities.value={};receiveCosts.value=[];receiveKey.value=crypto.randomUUID();receiveDate.value=props.today;await loadReceiveAccounts();await nextTick();orderDialog.value.showModal()}catch(e){error.value=e.message}}
async function openReceipt(name){try{receipt.value=await api('purchase_receipt',{name});receiptConfirm.value='';await nextTick();receiptDialog.value.showModal()}catch(e){error.value=e.message}}
const receiving=computed(()=>Object.fromEntries(Object.entries(receiveQuantities.value).filter(([,qty])=>Number(qty)>0)))
async function receive(){if(saving.value)return;saving.value=true;error.value='';try{const result=await api('receive_order',{name:order.value.name,posting_date:receiveDate.value,quantities:receiving.value,client_event_id:receiveKey.value,additional_costs:receiveCosts.value},true);orderDialog.value.close();await openReceipt(result.name);await load()}catch(e){error.value=e.message}finally{saving.value=false}}
async function actReceipt(action){if(saving.value)return;saving.value=true;error.value='';try{await api('receipt_action',{name:receipt.value.name,modified:receipt.value.modified,action},true);receiptDialog.value.close();notice.value=action==='submit'?'Đã ghi sổ nhận hàng. Tồn và phần chờ nhập đã cập nhật.':'Đã xóa phiếu nhận nháp.';await load()}catch(e){error.value=e.message}finally{saving.value=false}}
const unresolved=computed(()=>data.value?.unmapped||[])
defineExpose({refresh:()=>load(true),openReceipt})
</script>
<template>
 <div class="warehouse-planning">
  <p v-if="error" class="stock-error" role="alert">{{error}}</p><p v-if="notice" class="stock-success" role="status">{{notice}}</p>
  <div class="stock-date-filters stock-planning-toolbar"><slot name="scope"/><label>Từ ngày<UiInput v-model="from" type="date" @change="load(true)"/></label><label>Đến ngày<UiInput v-model="to" type="date" @change="load(true)"/></label><UiButton v-if="hasFilters" variant="outline" @click="resetFilters">Bỏ lọc</UiButton><slot name="actions"/><div class="stock-search stock-search--instant"><UiInput v-model="searchDraft" aria-label="Tìm nhu cầu và đơn mua" placeholder="Tìm vật tư, phiếu…"/></div></div>
  <div class="stock-issue-tabs"><UiButton variant="outline" :class="{active:view==='coverage'}" @click="view='coverage'">Nhu cầu vật tư</UiButton><UiButton variant="outline" :class="{active:view==='requests'}" @click="view='requests'">Đề nghị mua</UiButton><UiButton variant="outline" :class="{active:view==='orders'}" @click="view='orders'">Hàng chờ về</UiButton></div>
  <p v-for="warning in data?.warnings" :key="warning" class="stock-error" role="alert">{{warning}}</p>
  <section v-if="unresolved.length" class="planning-unmapped"><strong>Nhu cầu chưa xác định kho cấp</strong><div v-for="source in unresolved" :key="source.name+source.line"><span>{{source.name}} · {{source.item_name}} · {{fmt(source.remaining_qty)}} {{unit(source.uom)}} · {{source.area}}</span><UiSelect v-if="source.can_assign" v-model="selectedStores[source.name]" aria-label="Kho cấp cho nhu cầu"><option value="">Chọn kho cấp</option><option v-for="store in data.warehouses" :key="store.name" :value="store.name">{{store.warehouse_name}}</option></UiSelect><UiButton v-if="source.can_assign" variant="outline" :disabled="saving||!selectedStores[source.name]" @click="assign(source)">Gán kho</UiButton></div></section>
  <section class="stock-panel" v-if="view==='coverage'"><DataTable server-sort @sort="model=>{sortModel=model;load(true)}" show-empty-headers :rows="data?.rows||[]" :columns="columns" :loading="busy" :filter-values="data?.filter_values" :server-filters="filters" @filter="filter" interactive @open="show" empty="Chưa có nhu cầu vật tư đã duyệt trong khoảng ngày này."/><footer class="stock-pagination"><a href="/lotus/materials">Lập và duyệt nhu cầu vật tư</a><span>{{data?.total_count||0}} vật tư / kho</span><div><UiButton variant="outline" :disabled="!start||busy" @click="start-=50;load()">← Trước</UiButton><UiButton variant="outline" :disabled="!data?.has_more||busy" @click="start+=50;load()">Sau →</UiButton></div></footer></section>
  <section v-if="view==='requests'" class="stock-panel"><DataTable :rows="requestRows" :columns="requestColumns" show-empty-headers :loading="busy" interactive @open="row=>openRequest(row.name)" empty="Chưa có đề nghị mua còn chờ đặt hàng."/></section>
  <section v-if="view==='orders'" class="stock-panel"><DataTable :rows="orderRows" :columns="orderColumns" show-empty-headers :loading="busy" interactive @open="row=>openOrder(row.name)" empty="Chưa có đơn mua đã duyệt còn chờ nhận."/></section>
  <WorkspaceModal bare title="Nhu cầu vật tư" :busy="saving" ref="detailDialog" class="stock-dialog"><header><h2>{{detail?.item_name}} · {{detail?.warehouse}}</h2><UiButton variant="outline" aria-label="Đóng nhu cầu" @click="detailDialog.close()">✕</UiButton></header><p v-if="error" class="stock-error" role="alert">{{error}}</p><DataTable :rows="detail?.sources||[]" :columns="sourceColumns"/><div class="stock-summary planning-quantity-summary"><span>Tồn thực tế <strong>{{fmt(detail?.actual_qty)}}</strong></span><span>Giữ chỗ ERP <strong>{{fmt(detail?.native_reserved_qty)}}</strong></span><span>Phiếu nháp của nhu cầu khác <strong>{{fmt(detail?.other_hold_qty)}}</strong></span><span>Phiếu nháp của nhu cầu này <strong>{{fmt(detail?.own_draft_qty)}}</strong></span><span>Đã đề nghị mua <strong>{{fmt(detail?.requested_qty)}}</strong></span><span>Chưa đề nghị <strong>{{fmt(detail?.to_request_qty)}}</strong></span><span>Hàng hẹn sau kỳ <strong>{{fmt(detail?.later_incoming_qty)}}</strong></span></div><footer><UiButton v-if="data?.can_request&&detail?.to_request_qty>0" variant="default" :disabled="saving" @click="buy(detail)">Lập đề nghị mua {{fmt(detail?.to_request_qty)}} {{unit(detail?.uom)}}</UiButton><UiButton variant="outline" @click="detailDialog.close()">Đóng</UiButton></footer></WorkspaceModal>
  <WorkspaceModal bare title="Đề nghị mua" :busy="saving" ref="requestDialog" class="stock-dialog"><header><h2>Đề nghị mua · {{request?.name}}</h2><UiButton variant="outline" aria-label="Đóng đề nghị mua" @click="requestDialog.close()">✕</UiButton></header><p v-if="error" class="stock-error" role="alert">{{error}}</p><DataTable :rows="request?.items||[]" :columns="purchaseItems"/><p v-if="confirmAction" class="delete-confirm">{{confirmAction==='submit'?'Duyệt đề nghị mua này?':'Xóa đề nghị mua nháp này?'}}<UiButton variant="outline" @click="confirmAction=''">Quay lại</UiButton><UiButton variant="default" :disabled="saving" @click="act(confirmAction)">Xác nhận</UiButton></p><footer><a v-if="request" :href="printURL('Material Request',request.name)" target="_blank" rel="noopener" class="stock-button">In phiếu</a><UiButton v-if="request?.can_delete" variant="destructive" :disabled="saving" @click="confirmAction='delete'">Xóa nháp</UiButton><UiButton v-if="request?.can_submit" variant="default" :disabled="saving" @click="confirmAction='submit'">Duyệt đề nghị mua</UiButton></footer></WorkspaceModal>
  <WorkspaceModal bare title="Nhận hàng theo đơn" :busy="saving" ref="orderDialog" class="stock-dialog"><form @submit.prevent="receive"><header><h2>Nhận hàng · {{order?.name}} · {{order?.supplier}}</h2><UiButton variant="outline" aria-label="Đóng nhận hàng" @click="orderDialog.close()">✕</UiButton></header><p v-if="error" class="stock-error" role="alert">{{error}}</p><label>Ngày nhận<UiInput v-model="receiveDate" type="date" required/></label><div v-for="row in order?.items" :key="row.line" class="stock-line planning-receive-line"><div><strong>{{row.item_name}}</strong><small>{{row.item}} · {{row.warehouse}}</small><small>Đặt {{fmt(row.ordered_qty)}} · Đã nhận {{fmt(row.received_qty)}} · Phiếu nháp {{fmt(row.draft_qty)}} · Còn nhận {{fmt(row.remaining_qty)}} {{unit(row.uom)}}</small></div><div><small>Đơn giá theo đơn: {{fmt(row.rate)}} {{order?.currency||"VND"}} / {{unit(row.uom)}}</small><label>Thực nhận ({{unit(row.uom)}})<UiInput v-model.number="receiveQuantities[row.line]" type="number" min="0" :max="row.remaining_qty" step="any" :disabled="!row.remaining_qty||saving"/></label></div></div><PurchaseReceiptCosts v-model="receiveCosts" :accounts="receiveAccounts" :default-account="receiveDefaultAccount" :base-total="receiveBaseTotal" :currency="order?.currency||'VND'" :disabled="saving"/><footer><UiButton variant="default" type="submit" :disabled="saving||!order?.can_receive||!Object.keys(receiving).length">Lập phiếu nhận nháp</UiButton></footer></form></WorkspaceModal>
  <WorkspaceModal bare title="Phiếu nhận hàng" :busy="saving" ref="receiptDialog" class="stock-dialog"><header><h2>Nhận hàng · {{receipt?.name}}</h2><UiButton variant="outline" aria-label="Đóng phiếu nhận hàng" @click="receiptDialog.close()">✕</UiButton></header><p v-if="error" class="stock-error" role="alert">{{error}}</p><p class="stock-muted">{{receipt?.supplier}} · {{['Nháp','Đã ghi sổ','Đã hủy'][receipt?.docstatus]}}</p><DataTable :rows="receipt?.items||[]" :columns="purchaseItems"/><div v-if="receipt" class="receipt-totals"><span>Tiền hàng <strong>{{fmt(receipt.goods_total)}} {{receipt.currency}}</strong></span><span>Chi phí vào giá vốn <strong>{{fmt(receipt.valuation_charges)}} {{receipt.currency}}</strong></span><span>Giá trị nhập <strong>{{fmt(receipt.incoming_total)}} {{receipt.currency}}</strong></span></div><p v-if="receiptConfirm" class="delete-confirm">{{receiptConfirm==='submit'?'Ghi sổ số thực nhận này và cập nhật tồn kho?':'Xóa phiếu nhận hàng nháp này?'}}<UiButton variant="outline" @click="receiptConfirm=''">Quay lại</UiButton><UiButton variant="default" :disabled="saving" @click="actReceipt(receiptConfirm)">Xác nhận</UiButton></p><footer><a v-if="receipt" :href="printURL('Purchase Receipt',receipt.name)" target="_blank" rel="noopener" class="stock-button">In phiếu</a><UiButton v-if="receipt?.can_delete" variant="destructive" :disabled="saving" @click="receiptConfirm='delete'">Xóa nháp</UiButton><UiButton v-if="receipt?.can_submit" variant="default" :disabled="saving" @click="receiptConfirm='submit'">Ghi sổ nhận hàng</UiButton></footer></WorkspaceModal>
 </div>
</template>
